Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).
Module Ly := U1Layout.
Abbreviation SEGS := Ubsan.M.loaded_segments.

Definition PC_RET_RESIZE : Z := 0x69b78.
Definition PC_RETC : Z := 0x69a74.
Definition FUEL : nat := 400%nat.

Section DsCtorTail.
Context {AC : AllocCeiling}.
Context {RRND : RunRandom}.
  Variable MI : MallocIface SEGS Ly.L.
  Variable ST : StaticsIface SEGS Ly.L.
  Hypothesis DN : diag_needs MI ST.

  #[local] Notation cfg fx R pc M model := (mkCfg (@mkst fx R (Z_to_bv 64 pc) M (seg_rom SEGS)) model).

  Section Call.
    Context {fx : FPState}.
    Variables (A : AS MI) (s : LibIface.SX ST) (R : bvmap 5 word) (M : mem) (model : Model).
    Variables (sp ret ds ppos pcons pstr1 err pstr2 : Z) (K : TSet).
    Variable S : Z.
    Hypothesis CB : callB MI ST A s R M model sp ret S.
    Hypothesis HS : 224 <= S.
    Hypothesis ROC : ro_clear Ly.L M.
    Hypothesis Herr : - 2 ^ 31 <= err < 0.
    Hypothesis Hds : above_sp MI A sp ds 392 /\ ds mod 8 = 0 /\ mdef M ds 392.
    Hypothesis Hpos : above_sp MI A sp ppos 24 /\ mdef M ppos 24.
    Hypothesis Hs1 : above_sp MI A sp pstr1 24 /\ fld SEGS M pstr1 2 0 /\ mdef M pstr1 24.
    Hypothesis Hs2 : above_sp MI A sp pstr2 24 /\ fld SEGS M pstr2 2 0 /\ mdef M pstr2 24.
    Hypothesis Hs2al : pstr2 mod 8 = 0.
    Hypothesis Hcons : obj_ok MI A sp S pcons 48 /\ fld SEGS M (pcons + 32) 8 0.
    Hypothesis Hpc_hi : pcons + 48 <= 2 ^ 47.
    Hypothesis DISJ : forall a, zwin ds (ds + 392) a ->
        ~ zwin ppos (ppos + 24) a /\ ~ zwin pstr1 (pstr1 + 24) a /\ ~ zwin pstr2 (pstr2 + 24) a /\ ~ zwin pcons (pcons + 48) a.
    Hypothesis CONT : forall A' R' M' model' B,
        retB MI ST A' s R R' M' model model' ->
        ds_rep MI A' M' ds err 0 B ->
        blk_xfer [] B (live MI A) (live MI A') ->
        eff MI A A' M M' (sp - S, sp) (ds_foot ds B) ->
        srealizes SEGS (cfg fx R' ret M' model') K.

    Definition SVC : list word := [Z_to_bv 64 ret; getr R 8%bv; getr R 9%bv; getr R 18%bv; getr R 19%bv; getr R 20%bv; getr R 21%bv;
                                   getr R 22%bv; getr R 23%bv; getr R 24%bv; getr R 25%bv].

    Record cmid (R4 : bvmap 5 word) (M4 : mem) (vp0 vp1 vp2 v10 v11 v12 v20 v21 v22 : Z) : Prop := CMID {
      cm_st : stores_in (fun a => zwin (sp - 224) sp a \/ zwin ds (ds + 264) a) M M4;
      cm_r2 : getr R4 2%bv = Z_to_bv 64 (sp - 144); cm_r3 : getr R4 3%bv = Z_to_bv 64 (ly_gp Ly.L); cm_r4 : getr R4 4%bv = Z_to_bv 64 (ly_tp Ly.L);
      cm_r8 : getr R4 8%bv = Z_to_bv 64 (ds + 8); cm_r9 : getr R4 9%bv = Z_to_bv 64 (ds + 73); cm_r18 : getr R4 18%bv = Z_to_bv 64 0;
      cm_r19 : getr R4 19%bv = Z_to_bv 64 1; cm_r20 : getr R4 20%bv = Z_to_bv 64 pcons; cm_r21 : getr R4 21%bv = Z_to_bv 64 ppos;
      cm_cs : forall r, In r [26; 27]%bv -> getr R4 r = getr R r;

      cm_f40 : fld SEGS M4 (sp - 144 + 40) 8 0x6994c; cm_f32 : fld SEGS M4 (sp - 144 + 32) 8 pstr2;
      cm_f24 : fld SEGS M4 (sp - 144 + 24) 8 ds; cm_f16 : fld SEGS M4 (sp - 144 + 16) 8 (err mod 2 ^ 64); cm_f8 : fld SEGS M4 (sp - 144 + 8) 8 pstr1;
      cm_sl : slots SEGS M4 sp SVC;

      cm_def : mdef M4 ds 392;
      cm_d0 : fld SEGS M4 ds 8 VT_OS; cm_d8 : fld SEGS M4 (ds + 8) 8 VT_SB; cm_d16 : fld SEGS M4 (ds + 16) 8 LOC_IMP;
      cm_d24 : fld SEGS M4 (ds + 24) 8 0; cm_d32 : fld SEGS M4 (ds + 32) 8 0; cm_d40 : fld SEGS M4 (ds + 40) 8 0;
      cm_str : str_rep MI A M4 (ds + 72) SShort (repeat 0 22);
      cm_d96 : fld SEGS M4 (ds + 96) 8 (ds + 73); cm_d104 : fld SEGS M4 (ds + 104) 4 16;
      cm_d112 : fld SEGS M4 (ds + 112) 8 VT_IOS; cm_d120 : fld SEGS M4 (ds + 120) 4 DS_FL0; cm_d128 : fld SEGS M4 (ds + 128) 8 6;
      cm_d136 : fld SEGS M4 (ds + 136) 8 0; cm_d144 : fld SEGS M4 (ds + 144) 4 0; cm_d148 : fld SEGS M4 (ds + 148) 4 0;
      cm_d152 : fld SEGS M4 (ds + 152) 8 (ds + 8); cm_d160 : fld SEGS M4 (ds + 160) 8 LOC_IMP;
      cm_zero : forall i, 0 <= i < 10 -> fld SEGS M4 (ds + 168 + 8 * i) 8 0;
      cm_d248 : fld SEGS M4 (ds + 248) 8 0; cm_d256 : fld SEGS M4 (ds + 256) 4 (2 ^ 32 - 1);

      cm_p0 : cellw SEGS M4 ppos 8 vp0; cm_p1 : cellw SEGS M4 (ppos + 8) 8 vp1; cm_p2 : cellw SEGS M4 (ppos + 16) 8 vp2;
      cm_c32 : fld SEGS M4 (pcons + 32) 8 0;
      cm_s1z : fld SEGS M4 pstr1 2 0; cm_s10 : cellw SEGS M4 pstr1 8 v10; cm_s11 : cellw SEGS M4 (pstr1 + 8) 8 v11; cm_s12 : cellw SEGS M4 (pstr1 + 16) 8 v12;
      cm_s2z : fld SEGS M4 pstr2 2 0; cm_s20 : cellw SEGS M4 pstr2 8 v20; cm_s21 : cellw SEGS M4 (pstr2 + 8) 8 v21; cm_s22 : cellw SEGS M4 (pstr2 + 16) 8 v22
    }.

    Lemma ctor_tail : forall R4 M4 vp0 vp1 vp2 v10 v11 v12 v20 v21 v22,
